functions.pseudocode:
// (only the z-order-relevant parts of the entry point)
indices.clear();
vertices = 0;
if (points.empty()) return;

double x;
double y;
int threshold = 80;
std::size_t len = 0;

// NOTE: this loop SHORT-CIRCUITS on threshold >= 0, so `len` is a
// partial sum when there are many rings. len is only used for the
// node-pool reservation, so it does not affect output.
for (size_t i = 0; threshold >= 0 && i < points.size(); i++) {
    threshold -= static_cast<int>(points[i].size());
    len += points[i].size();
}

nodes.reset(len * 3 / 2);          // node pool sizing estimate only
indices.reserve(len + points[0].size());

Node* outerNode = linkedList(points[0], true);
if (!outerNode || outerNode->prev == outerNode->next) return;

if (points.size() > 1) outerNode = eliminateHoles(points, outerNode);

// if the shape is not too simple, we'll use z-order curve hash later;
// calculate polygon bbox
hashing = threshold < 0;
if (hashing) {
    Node* p = outerNode->next;
    minX = maxX = outerNode->x;
    minY = maxY = outerNode->y;
    do {
        x = p->x;
        y = p->y;
        minX = std::min<double>(minX, x);
        minY = std::min<double>(minY, y);
        maxX = std::max<double>(maxX, x);
        maxY = std::max<double>(maxY, y);
        p = p->next;
    } while (p != outerNode);

    // minX, minY and inv_size are later used to transform coords
    // into integers for z-order calculation
    inv_size = std::max<double>(maxX - minX, maxY - minY);
    inv_size = inv_size != .0 ? (32767. / inv_size) : .0;
}

earcutLinked(outerNode);

nodes.clear();

// z-order of a point given coords and size of the data bounding box

// coords are transformed into non-negative 15-bit integer range
int32_t x = static_cast<int32_t>((x_ - minX) * inv_size);
int32_t y = static_cast<int32_t>((y_ - minY) * inv_size);

x = (x | (x << 8)) & 0x00FF00FF;
x = (x | (x << 4)) & 0x0F0F0F0F;
x = (x | (x << 2)) & 0x33333333;
x = (x | (x << 1)) & 0x55555555;

y = (y | (y << 8)) & 0x00FF00FF;
y = (y | (y << 4)) & 0x0F0F0F0F;
y = (y | (y << 2)) & 0x33333333;
y = (y | (y << 1)) & 0x55555555;

return x | (y << 1);

// interlink polygon nodes in z-order
assert(start);
Node* p = start;

do {
    p->z = p->z ? p->z : zOrder(p->x, p->y);
    p->prevZ = p->prev;
    p->nextZ = p->next;
    p = p->next;
} while (p != start);

// p == start here
p->prevZ->nextZ = nullptr;
p->prevZ = nullptr;

sortLinked(p);   // return value intentionally discarded

// Simon Tatham's linked list merge sort algorithm
// http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
assert(list);
Node* p;
Node* q;
Node* e;
Node* tail;
int i, numMerges, pSize, qSize;
int inSize = 1;

for (;;) {
    p = list;
    list = nullptr;
    tail = nullptr;
    numMerges = 0;

    while (p) {
        numMerges++;
        q = p;
        pSize = 0;
        for (i = 0; i < inSize; i++) {
            pSize++;
            q = q->nextZ;
            if (!q) break;
        }

        qSize = inSize;

        while (pSize > 0 || (qSize > 0 && q)) {

            if (pSize == 0) {
                e = q;
                q = q->nextZ;
                qSize--;
            } else if (qSize == 0 || !q) {
                e = p;
                p = p->nextZ;
                pSize--;
            } else if (p->z <= q->z) {
                e = p;
                p = p->nextZ;
                pSize--;
            } else {
                e = q;
                q = q->nextZ;
                qSize--;
            }

            if (tail) tail->nextZ = e;
            else list = e;

            e->prevZ = tail;
            tail = e;
        }

        p = q;
    }

    tail->nextZ = nullptr;

    if (numMerges <= 1) return list;

    inSize *= 2;
}

const Node* a = ear->prev;
const Node* b = ear;
const Node* c = ear->next;

if (area(a, b, c) >= 0) return false;   // reflex, can't be an ear
// area(p,q,r) == (q->y - p->y) * (r->x - q->x) - (q->x - p->x) * (r->y - q->y)

// triangle bbox; min & max are calculated like this for speed
const double minTX = std::min<double>(a->x, std::min<double>(b->x, c->x));
const double minTY = std::min<double>(a->y, std::min<double>(b->y, c->y));
const double maxTX = std::max<double>(a->x, std::max<double>(b->x, c->x));
const double maxTY = std::max<double>(a->y, std::max<double>(b->y, c->y));

// z-order range for the current triangle bbox;
const int32_t minZ = zOrder(minTX, minTY);
const int32_t maxZ = zOrder(maxTX, maxTY);

Node* p = ear->prevZ;
Node* n = ear->nextZ;

// look for points inside the triangle in both directions
while (p && p->z >= minZ && n && n->z <= maxZ) {
    if (p->x >= minTX && p->x <= maxTX && p->y >= minTY && p->y <= maxTY &&
        p != ear->prev && p != ear->next &&
        pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
        area(p->prev, p, p->next) >= 0) return false;
    p = p->prevZ;

    if (n->x >= minTX && n->x <= maxTX && n->y >= minTY && n->y <= maxTY &&
        n != ear->prev && n != ear->next &&
        pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, n->x, n->y) &&
        area(n->prev, n, n->next) >= 0) return false;
    n = n->nextZ;
}

// look for remaining points in decreasing z-order
while (p && p->z >= minZ) {
    if (p != ear->prev && p != ear->next &&
        p->x >= minTX && p->x <= maxTX && p->y >= minTY && p->y <= maxTY &&
        pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, p->x, p->y) &&
        area(p->prev, p, p->next) >= 0) return false;
    p = p->prevZ;
}

// look for remaining points in increasing z-order
while (n && n->z <= maxZ) {
    if (n != ear->prev && n != ear->next &&
        n->x >= minTX && n->x <= maxTX && n->y >= minTY && n->y <= maxTY &&
        pointInTriangle(a->x, a->y, b->x, b->y, c->x, c->y, n->x, n->y) &&
        area(n->prev, n, n->next) >= 0) return false;
    n = n->nextZ;
}

return true;

if (!ear) return;

// interlink polygon nodes in z-order
if (!pass && hashing) indexCurve(ear);

Node* stop = ear;
Node* prev;
Node* next;

// iterate through ears, slicing them one by one
while (ear->prev != ear->next) {
    prev = ear->prev;
    next = ear->next;

    if (hashing ? isEarHashed(ear) : isEar(ear)) {
        // cut off the triangle
        indices.emplace_back(prev->i);
        indices.emplace_back(ear->i);
        indices.emplace_back(next->i);

        removeNode(ear);

        // skipping the next vertex leads to less sliver triangles
        ear = next->next;
        stop = next->next;

        continue;
    }

    ear = next;

    // if we looped through the whole remaining polygon and can't find any more ears
    if (ear == stop) {
        // try filtering points and slicing again
        if (!pass) earcutLinked(filterPoints(ear), 1);

        // if this didn't work, try curing all small self-intersections locally
        else if (pass == 1) {
            ear = cureLocalIntersections(filterPoints(ear));
            earcutLinked(ear, 2);

        // as a last resort, try splitting the remaining polygon into two
        } else if (pass == 2) splitEarcut(ear);

        break;
    }
}

functions.notes:
INDEXCURVE IS CALLED ONLY WHEN `pass == 0` AND `hashing` — i.e. `if (!pass && hashing) indexCurve(ear);`. It is therefore called: (1) once from the top-level `earcutLinked(outerNode)`, and (2) once per half from `splitEarcut`, which invokes `earcutLinked(a)` / `earcutLinked(c)` with the defaulted pass 0. The pass-1 and pass-2 recursive retries do NOT re-index — they reuse the existing (possibly partially unlinked) z chain.

Crucially `hashing` (not `pass`) selects isEarHashed vs isEar, so pass 1 and 2 still use isEarHashed on a chain that was indexed during pass 0.

removeNode keeps the z chain consistent:
  p->next->prev = p->prev;
  p->prev->next = p->next;
  if (p->prevZ) p->prevZ->nextZ = p->nextZ;
  if (p->nextZ) p->nextZ->prevZ = p->prevZ;
so cut ears and filtered-out collinear points vanish from the z chain immediately. Note the removed node's own prevZ/nextZ are NOT cleared.

Nodes minted by splitPolygon (hole bridges, splitEarcut diagonals) have z == 0 and null prevZ/nextZ until an indexCurve pass adopts them; a hole-bridge node created before the top-level earcutLinked is adopted normally, whereas a splitEarcut diagonal node is adopted by the immediately following earcutLinked(a)/earcutLinked(c).
